import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 부수를 보내지 않으면 1부로 신청한다.
const DEFAULT_COPIES = 1;
// 가정: 채번 자릿수가 비어 있으면 4자리로 한다.
const DEFAULT_DIGITS = 4;

@Controller('api/v1')
export class FnSfr01603Controller {
  @Post('/certificate-requests')
  @HttpCode(200)
  async createCertificateRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const rawType = data['certificateTypeId'];
    const typeId = Number(rawType);
    if (rawType === undefined || rawType === null || rawType === '' || !Number.isInteger(typeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증명서 종류를 선택해 주세요.');
    }
    const rawPurpose = data['purpose'];
    if (rawPurpose !== undefined && rawPurpose !== null && (typeof rawPurpose !== 'string' || rawPurpose.length > 200)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '용도는 200자 이내의 글자로 입력해 주세요.');
    }
    const purpose = typeof rawPurpose === 'string' ? rawPurpose : '';
    const rawCopies = data['copies'];
    let copies = DEFAULT_COPIES;
    if (rawCopies !== undefined && rawCopies !== null && rawCopies !== '') {
      copies = Number(rawCopies);
      if (!Number.isInteger(copies) || copies <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '부수는 1 이상의 정수로 입력해 주세요.');
      }
    }
    return transaction(async (db) => {
      const types = await db.query(
        `SELECT use_yn AS "useYn" FROM certificate_type WHERE certificate_type_id = CAST(:typeId AS bigint)`,
        { typeId },
      );
      if (types.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_TYPE_NOT_FOUND', '증명서 종류를 찾을 수 없습니다.');
      }
      if (types[0]['useYn'] !== '사용') {
        throw new ApiError(422, 'CERTIFICATE_TYPE_NOT_IN_USE', '사용하지 않는 증명서 양식은 신청할 수 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO certificate_request
           (certificate_type_id, employee_id, purpose, copies, status, created_at, updated_at)
         VALUES
           (CAST(:typeId AS bigint), CAST(:userId AS bigint), :purpose, CAST(:copies AS integer), '신청', now(), now())
         RETURNING certificate_request_id AS "certificateRequestId", status AS "status"`,
        { typeId, userId: user.id, purpose, copies },
      );
      return rows[0];
    });
  }

  @Post('/certificate-requests/:certificateRequestId/approve')
  @HttpCode(200)
  async approveCertificateRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const idText = req.params['certificateRequestId'];
    const id = Number(idText);
    if (!Number.isInteger(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 번호 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status", certificate_type_id AS "typeId"
           FROM certificate_request
          WHERE certificate_request_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_REQUEST_NOT_FOUND', '증명서 신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_REQUEST_ALREADY_PROCESSED', '이미 승인 또는 반려된 신청 건입니다.');
      }
      const typeId = found[0]['typeId'];
      const types = await db.query(
        `SELECT numbering_prefix AS "prefix",
                numbering_digits AS "digits",
                numbering_reset_cycle AS "resetCycle",
                last_sequence AS "lastSequence",
                to_char(now(), 'YYYY') AS "year"
           FROM certificate_type
          WHERE certificate_type_id = CAST(:typeId AS bigint)
            FOR UPDATE`,
        { typeId },
      );
      const type = types[0];
      // 가정: 발급번호 형식은 접두어 + 연도 + '-' + 일련번호(자릿수만큼 0 채움)이다.
      const prefix = type['prefix'] ? String(type['prefix']) : '';
      const digits = type['digits'] ? Number(type['digits']) : DEFAULT_DIGITS;
      const year = String(type['year']);
      const head = prefix + year + '-';
      let seq = Number(type['lastSequence'] ?? 0) + 1;
      if (type['resetCycle'] === '연') {
        // 가정: 연 단위 초기화는 같은 해에 이미 발급된 번호의 최댓값에 1을 더해 구한다.
        const maxRows = await db.query(
          `SELECT COALESCE(MAX(CAST(substring(issue_number from '[0-9]+$') AS integer)), 0) AS "maxSeq"
             FROM certificate_request
            WHERE certificate_type_id = CAST(:typeId AS bigint)
              AND issue_number LIKE :pattern`,
          { typeId, pattern: head + '%' },
        );
        seq = Number(maxRows[0]['maxSeq']) + 1;
      }
      const issueNumber = head + String(seq).padStart(digits, '0');
      await db.execute(
        `UPDATE certificate_type
            SET last_sequence = CAST(:seq AS integer), updated_at = now()
          WHERE certificate_type_id = CAST(:typeId AS bigint)`,
        { seq, typeId },
      );
      const rows = await db.query(
        `UPDATE certificate_request
            SET status = '승인', issue_number = :issueNumber, updated_at = now()
          WHERE certificate_request_id = CAST(:id AS bigint)
          RETURNING status AS "status", issue_number AS "issueNumber"`,
        { issueNumber, id },
      );
      return rows[0];
    });
  }

  @Post('/certificate-requests/:certificateRequestId/reject')
  @HttpCode(200)
  async rejectCertificateRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const idText = req.params['certificateRequestId'];
    const id = Number(idText);
    if (!Number.isInteger(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 번호 형식이 올바르지 않습니다.');
    }
    const rawReason = data['rejectReason'];
    if (typeof rawReason !== 'string' || rawReason.trim() === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    const rejectReason = rawReason.trim();
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status"
           FROM certificate_request
          WHERE certificate_request_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_REQUEST_NOT_FOUND', '증명서 신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_REQUEST_ALREADY_PROCESSED', '이미 승인 또는 반려된 신청 건입니다.');
      }
      const rows = await db.query(
        `UPDATE certificate_request
            SET status = '반려', reject_reason = :rejectReason, updated_at = now()
          WHERE certificate_request_id = CAST(:id AS bigint)
          RETURNING status AS "status"`,
        { rejectReason, id },
      );
      return rows[0];
    });
  }
}

