import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, RefName, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

type Panel = { kind: 'create' } | { kind: 'reject'; row: Row } | null;

export default function FnSfr01603Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [panel, setPanel] = useState<Panel>(null);
  const [typeId, setTypeId] = useState<number | string>('');
  const [purpose, setPurpose] = useState('');
  const [copies, setCopies] = useState<number | string>(1);
  const [reason, setReason] = useState('');

  function patchRow(id: unknown, patch: Row) {
    setRows((prev) => prev.map((r) => (r['certificateRequestId'] === id ? { ...r, ...patch } : r)));
  }

  function openCreate() {
    setTypeId('');
    setPurpose('');
    setCopies(1);
    setPanel({ kind: 'create' });
  }

  function openReject(row: Row) {
    setReason('');
    setPanel({ kind: 'reject', row });
  }

  async function create() {
    if (typeId === '') {
      throw new Error('증명서 종류를 선택해 주세요.');
    }
    const res = await call('POST', '/certificate-requests', role, {
      certificateTypeId: typeId,
      purpose,
      copies,
    });
    setRows((prev) => [
      {
        certificateRequestId: res['certificateRequestId'],
        certificateTypeId: typeId,
        purpose,
        copies,
        status: res['status'],
        issueNumber: '',
      },
      ...prev,
    ]);
    notify('증명서를 신청했습니다.');
    setPanel(null);
  }

  async function approve(row: Row) {
    try {
      const res = await call('POST', '/certificate-requests/' + String(row['certificateRequestId']) + '/approve', role, {});
      patchRow(row['certificateRequestId'], { status: res['status'], issueNumber: res['issueNumber'] });
      notify('승인했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '승인하지 못했습니다.');
    }
  }

  async function reject(row: Row) {
    if (reason.trim() === '') {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    const res = await call('POST', '/certificate-requests/' + String(row['certificateRequestId']) + '/reject', role, {
      rejectReason: reason,
    });
    patchRow(row['certificateRequestId'], { status: res['status'] });
    notify('반려했습니다.');
    setPanel(null);
  }

  return (
    <div className="doc">
      <h1>증명서 신청 검토·승인</h1>
      <Band total={rows.length}>
        <button onClick={openCreate}>증명서 신청</button>
      </Band>
      <DataTable
        rows={rows}
        empty="아직 처리한 내역이 없습니다. 증명서 신청 버튼으로 시작해 주세요."
        columns={[
          { key: 'certificateRequestId', label: '증명서 신청 ID' },
          {
            key: 'certificateTypeId',
            label: '증명서 종류',
            render: (r) => <RefName table="certificate_type" role={role} value={r['certificateTypeId']} />,
          },
          { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
          { key: 'issueNumber', label: '발급번호' },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r['status'] === '신청' ? (
                <span>
                  <button className="ghost" onClick={() => approve(r)}>승인</button>
                  <button className="ghost" onClick={() => openReject(r)}>반려</button>
                </span>
              ) : null,
          },
        ]}
      />
      {panel && panel.kind === 'create' && (
        <Drawer title="증명서 신청" onClose={() => setPanel(null)}>
          <Form onSubmit={create} submit="신청">
            <Field label="증명서 종류 ID" required>
              <LookupSelect table="certificate_type" role={role} value={typeId} onChange={setTypeId} />
            </Field>
            <Field label="용도">
              <TextInput value={purpose} onChange={setPurpose} />
            </Field>
            <Field label="부수">
              <NumberInput value={copies} onChange={setCopies} />
            </Field>
          </Form>
        </Drawer>
      )}
      {panel && panel.kind === 'reject' && (
        <Drawer title="증명서 신청 반려" onClose={() => setPanel(null)}>
          <Form
            onSubmit={() => reject(panel.row)}
            submit="반려"
            danger
            note="반려하면 이 신청 건은 다시 처리할 수 없습니다."
          >
            <Field label="반려 사유" required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
